/// <summary>
///
/// </summary>
public static void populateTmpData(MZNAGSalesId _salesId)
{
    MZNAG_SalesPickingLinesTmp pickingTmp;
    MZNAG_SalesLine           salesLine;

    while select salesLine
    where salesLine.SalesId == _salesId
    {
        real remainingQty = salesLine.SalesQty - salesLine.PickedQty;

        if (remainingQty > 0)
        {
            pickingTmp.clear();

            pickingTmp.SalesId             = salesLine.SalesId;
            pickingTmp.LineNum             = salesLine.LineNum;
            pickingTmp.ItemId              = salesLine.ItemId;
            pickingTmp.ItemName            = salesLine.ItemName;
            pickingTmp.InventSiteId        = salesLine.InventSiteId;
            pickingTmp.InventLocationId    = salesLine.InventLocationId;
            pickingTmp.PickedQty           = remainingQty;
            pickingTmp.QtyToPick           = remainingQty;
            pickingTmp.insert();
        }
    }
}
